window.VstepIdeaData = [
  {id:"technology", icon:"📺", label:"CÔNG NGHỆ", html:"<div style=\"font-size:0.85rem;line-height:1.6;\"><div style=\"display:flex;font-weight:700;font-size:0.88rem;color:var(--primary);margin:8px 0 4px;\"><span style=\"flex:1;padding-right:10px;\">Positives of Mobile Phones</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-weight:400;font-size:0.8rem;color:var(--text-muted);font-style:italic;\">Ưu điểm của điện thoại</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• The mobile phone is the most popular gadget in today’s world</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Ngày nay điện thoại là phương tiện phổ biển nhất trên thế giới</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Mobile phones have revolutionized the way we communicate</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Điện thoại thay đổi cách chúng ta giao tiếp với nhau</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• We can stay in touch with family, friends and colleagues wherever we are</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Chúng ta có thể liên lạc với gia đình, bạn bè và đồng nghiệp ở bất cứ nơi đâu</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Users can send text messages, surf the Internet, take photos and listen to music</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Người dùng có thể gửi tin nhắn, lướt Web, chụp ảnh và nghe nhạc</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Mobiles have also become fashion accessories</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Điện thoại cũng trở thành món phụ kiện thời trang</span></div><br><div style=\"display:flex;font-weight:700;font-size:0.88rem;color:var(--primary);margin:8px 0 4px;\"><span style=\"flex:1;padding-right:10px;\">Positives of television</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-weight:400;font-size:0.8rem;color:var(--text-muted);font-style:italic;\">Lợi ích của xem ti vi</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Watching television is a good way to relax</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Xem ti vi là một cách hay để giải trí</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• It is many people’s favorite way to wind down after a hard day at work</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Đây là cách giải trí yêu thích của nhiều người sau một ngày làm việc mệt mỏi</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Television programs can be entertaining and enjoyable</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Các chương trình ti vi có thể mang tính giải trí và thú vị</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Viewers have access to a huge variety of entertainment channels</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Người xem có thể truy cập vào nhiều kênh giải trí khác nhau</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• elevision brings the best comedians, musicians and actors into our homes Ti vi</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">đưa những diễn viên hài, nghệ sĩ và diễn viên gỏi nhất đến với công chúng</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Programmers can also be informative and educational</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Các chương trình cũng có thể cung cấp thông tin và mang tính giáo dục</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• News coverage makes the public aware of events around the world</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Chương trình tin tức khiến cho công chúng biết được các sự kiện trên toàn thế giới</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Documentaries can make learning more interesting</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Các bộ phim tài liệu khiến học hành thú vị</span></div><br><div style=\"display:flex;font-weight:700;font-size:0.88rem;color:var(--primary);margin:8px 0 4px;\"><span style=\"flex:1;padding-right:10px;\">Negatives of Television</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-weight:400;font-size:0.8rem;color:var(--text-muted);font-style:italic;\">Bất lợi của xem ti vi</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Television is having a negative impact on society</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Tivi có ảnh hưởng tiêu cực đến xã hội</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Some people link violence on television with crime rates in the real world</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Một số người cho rằng bạo lực trên tivi có liên quan đến tội phạm trong cuộc sống thực</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Children copy the behavior they see on the screen</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Trẻ em bắt chước hành vi khi chúng xem được trên màn hình</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Children are less healthy because they spend less time playing</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Trẻ em không được khỏe mạnh lắm vì chúng dành ít thời gian vui chơi</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Advertisers direct their marketing at children</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Những nhà quảng cáo hướng quảng cáo đến trẻ em</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Watching TV is a waste of time</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Xem tivi tốn thời gian</span></div><br><div style=\"display:flex;font-weight:700;font-size:0.88rem;color:var(--primary);margin:8px 0 4px;\"><span style=\"flex:1;padding-right:10px;\">Opinions about Television</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-weight:400;font-size:0.8rem;color:var(--text-muted);font-style:italic;\">Quan điểm về xem Tivi</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Television has many benefits</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Tivi có nhiều lợi ích</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• However, it can be addictive</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Tuy nhiên, nó có thể gây nghiện</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Children should play outside rather than sit in front of a screen all day</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Trẻ con nên ra ngoài chơi thay vì ngồi trước màn hình suốt ngày</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Behaviour shown on TV can influence people</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Những hành vi trên Tivi có thể ảnh hưởng đến con người</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Parents should choose carefully what their children watch</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Bố mẹ nên chọn nội dung cho trẻ xem cẩn thận</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Children should not be exposed to violence, swearing or sexual images</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Trẻ không nên tiếp xúc với bạo lực hoặc những hình ảnh khiêu dâm</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Advertising during children’s programs should be strictly controlled</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Quảng cáo các chương trình cho trẻ em nên được kiểm soát nghiêm ngặt</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• TV companies should make more positive, educational programs</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Các công ty truyền hình nên làm các chương trình mang tính giáo dục và tích cực</span></div><br><div style=\"display:flex;font-weight:700;font-size:0.88rem;color:var(--primary);margin:8px 0 4px;\"><span style=\"flex:1;padding-right:10px;\">Positives of the Internet</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-weight:400;font-size:0.8rem;color:var(--text-muted);font-style:italic;\">Lợi ích của Internet</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• There are many advantages to using the Internet</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Dùng internet có nhiều lợi ích</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• It gives us instant access to information on almost any subject</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Nó cho phép truy cập thông tin ở hầu hết các lĩnh vực ngay lập tức</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Shops and other services are now available online</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Các cửa hàng và dịch vụ khác bán trực tuyến</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• People can buy goods and services from the comfort of their homes</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Mọi người có thể mua hàng hóa và dịch vụ tiện lợi khi đang ở nhà The</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Internet is starting to replace other forms of entertainment</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Internet đang dần thay thế các phương tiện giải trí khác</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• It has revolutionized communication</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Nó tạo ra một cách mạng trong giao tiếp</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• We can keep in touch by email or instant messenger services</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Chúng ta có thể liên lạc qua Email hoặc nhắn tin</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Video messaging is becoming common for business meetings</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Nhắn tin đang trở nên phổ biến trong các cuộc họp doanh nghiệp</span></div><br><div style=\"display:flex;font-weight:700;font-size:0.88rem;color:var(--primary);margin:8px 0 4px;\"><span style=\"flex:1;padding-right:10px;\">Negatives of the internet</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-weight:400;font-size:0.8rem;color:var(--text-muted);font-style:italic;\">Nhược điểm của Internet</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Many websites contain offensive content</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Nhiều trang website có thể chứa nội dung phản cảm</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Some sites show violent or sexual images</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Một số trang web đăng hình ảnh bạo lực hoặc khiêu dâm</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Parents find it difficult to control what their children see online</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Bố mẹ cảm thấy khó kiểm soát những thứ mà con cái họ xem trên mạng</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• They do not always know who their children are chatting to</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Không phải lúc nào họ cũng biết con mình đang chát với ai</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• With so many websites it is difficult to search for good information</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Có quá nhiều trang Web nên rất khó tìm kiếm thông tin hữu ích</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Criminals increasingly use the Internet to steal people’s money</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Tội phạm ngày càng sử dụng Internet để lấy trộm tiền của mọi người</span></div><br><div style=\"display:flex;font-weight:700;font-size:0.88rem;color:var(--primary);margin:8px 0 4px;\"><span style=\"flex:1;padding-right:10px;\">Internet compared to newspaper and books</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-weight:400;font-size:0.8rem;color:var(--text-muted);font-style:italic;\">So sánh Internet với sách báo</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Newspapers and books are now published online as well as in print</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Ngày này báo chí và sách vở được xuất bản trực tuyến cũng như bản giấy</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• We can read the news in any language from any country in the world</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Chúng ta có thể đọc tin tức bằng bất cứ ngôn ngữ nào từ bất kỳ quốc gia nào trên thế giới</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• It costs nothing to publish or access information on the Internet</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Không mất gì khi xuất bản hay truy cập thông tin trên mạng</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• The Internet allows anybody to publish their own writing</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Internet cho phép tất cả mọi người xuất bản bài viết của họ</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Newspaper articles and books are written by professionals</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Các bài báo hoặc sách được các chuyên gia viết</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Professionals produce better quality writing than amateur</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Các chuyên gia cung cấp những bài viết chất lượng hơn những người nghiệp dư</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• People still buy newspapers and books because they are portable</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Mọi người vẫn mua báo giấy và sách vở vì chúng dễ dàng mang theo</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• People do not like reading from a screen</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Mọi người không thích đọc trên màn hình</span></div><br><div style=\"display:flex;font-weight:700;font-size:0.88rem;color:var(--primary);margin:8px 0 4px;\"><span style=\"flex:1;padding-right:10px;\">Negatives of Mobile Phones</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-weight:400;font-size:0.8rem;color:var(--text-muted);font-style:italic;\">Nhược điểm của điện thoại</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Mobiles phones can be a problem in some public places</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Điện thoại có thể là vấn đề khi sử dụng ở nơi công cộng</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Ringing phones cause disturbance in cinemas and school lessons</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Chuông điện thoại gây khó chịu khi đi xem phim hoặc trong lớp học</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Some people are not aware that others can hear their conversations</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Một số người không nhận thức được rằng người khác sẽ nghe thấy cũng nói chuyên của họ</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Mobile phones may also interfere with electronic equipment</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Điện thoại cũng có thể gây nhiễu các thiết bị điện tử</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Their waves could cause damage to our brains</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Sóng điện thoại có thể gây hại đến não</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Mobile phones can also be a dangerous distraction</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Điện thoại cũng có thể gây sao nhãng một cách nguy hiển</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Using a phone while driving reduces the driver’s concentration</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Sử dụng điện thoại trong khi lái xe làm giảm độ tập trung</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Mobile phones are a popular target for thieves</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Điện thoại là mục tiêu phổ biến của bọn cướp</span></div><br><div style=\"display:flex;font-weight:700;font-size:0.88rem;color:var(--primary);margin:8px 0 4px;\"><span style=\"flex:1;padding-right:10px;\">Opinion about Mobile Phones</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-weight:400;font-size:0.8rem;color:var(--text-muted);font-style:italic;\">Quan điểm về điện thoại</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• The benefits of mobile phones outweigh the drawbacks</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Lợi ích của điện thoại nhiều hơn tác hại của nó</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• We need to use these phones with care</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Mọi người cần sử dụng điện thoại một cách cẩn thận 2. WORK – CÔNG VIỆC</span></div></div>"},
  {id:"work", icon:"💼", label:"CÔNG VIỆC", html:"<div style=\"font-size:0.85rem;line-height:1.6;\"><div style=\"display:flex;font-weight:700;font-size:0.88rem;color:var(--primary);margin:8px 0 4px;\"><span style=\"flex:1;padding-right:10px;\">The benefits of staying in the same job for life</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-weight:400;font-size:0.8rem;color:var(--text-muted);font-style:italic;\">Lợi ích khi làm một việc suốt đời</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Employees have a stable career with one employer</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Nhân viên có một công việc ổn định tại một doanh nghiêpj</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• They have a good pension and health insurance</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Nhân viên có lương hưu và bảo hiểm y tế</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Their salaries gradually increase</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Lương tăng đều</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• They may be promoted within the organization</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Có khả năng được thăng tiến</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• They demonstrate loyalty</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Thể hiện sự trung thành</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Experienced staff can be trusted with more responsibility</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Nhân viên giàu kinh nghiệm được tin tưởng và giao nhiều trọng trách hơn</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• They become part of a team</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Trở thành một phần của nhóm</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• There is a clearly defined path for development</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Có định hướng phát triển rõ ràng</span></div><br><div style=\"display:flex;font-weight:700;font-size:0.88rem;color:var(--primary);margin:8px 0 4px;\"><span style=\"flex:1;padding-right:10px;\">The benefits of not staying in the same job</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-weight:400;font-size:0.8rem;color:var(--text-muted);font-style:italic;\">Lợi ích của thay đổi công việc (nhảy việc) People often change jobs in order to further their career</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span data-vi=\"1\" style=\"flex:1;font-size:0.82rem;\">Mọi người thường thay đổi công việc để tìm kiếm sự thăng tiến</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Another company may offer a promotion or a higher salary</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Công ty khác có thể cân nhắc ở vị trí cao hơn hoặc là lương cao hơn</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• People who change jobs can gain experience</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Người thay đổi công việc có thêm kinh nghiệm</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• They can learn different skills</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Họ có thể học đươc những kỹ năng khác nhau</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Changing jobs is interesting and challenging</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Thay đổi công việc khá thú vị nhưng cũng đầy thử thách</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• People can retrain in a different occupation</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Mọi người được đào tạo lại khi làm công việc khác</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• In a fast-changing world workers need to be flexible</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Trong thế giới biến động nhanh chóng thì con người cần phải linh hoạt</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• People need to develop a range of experience and skills</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Con người cần phải tích lũy kinh nghiệm và phát triển kỹ năng</span></div><br><div style=\"display:flex;font-weight:700;font-size:0.88rem;color:var(--primary);margin:8px 0 4px;\"><span style=\"flex:1;padding-right:10px;\">Self</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-weight:400;font-size:0.8rem;color:var(--text-muted);font-style:italic;\">employment – Chủ doanh nghiệp</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Nowadays, it is easy to set up a company</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Ngày nay, thành lập công ty rất đơn giản</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• The Internet provides a global marketplace</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Internet trở thành chợ toàn cầu</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Self-employment offers greater freedom than working for a company</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Làm chủ có nhiều sự tự do hơn cho các công ty khác</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• However, there are risks to starting a new business</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Tuy nhiên, có nhiều thử thách khi khởi nghiệp</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Self-employed people may face financial difficulties</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Ông chủ có thể phải đối mặt với thử thách về tài chính</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Many businesses fail to make a profit</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Nhiều doanh nghiệp không kiếm ra lợi nhuận</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• There is less stability in self-employment</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Làm chủ công việc không ổn định bằng làm thuê</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• There are no benefits like pensions, sick pay and holiday pay</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">làm chủ người ta không nhận được lương hưu, tiền nghỉ ốm hay đi du lịch miễn phí Self-employment</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• involved hard work, long hours and total responsibility</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Làm chủ phải chăm chỉ, làm việc nhiều giờ và phải chịu hoàn toàn trách nhiệm</span></div><br><div style=\"display:flex;font-weight:700;font-size:0.88rem;color:var(--primary);margin:8px 0 4px;\"><span style=\"flex:1;padding-right:10px;\">Unemployment</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-weight:400;font-size:0.8rem;color:var(--text-muted);font-style:italic;\">Thất nghiệp</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Unemployment is a big problem for individuals, communities and society Some people are unable to find a job</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Thất nghiệp là một vấn đề lớn của cộng đồng, cá nhân và xã hội</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• They may not have the sufficient level of education or qualifications</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Họ có thể chưa được đào tạo bài bản hoặc chưa có bằng cấp</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• They may find themselves homeless</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Họ có thể bị vô gia cư</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Unemployment causes frustration and stress</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Thất nghiệp khiến người ta tuyệt vọng và căng thẳng</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Jobless people may become involved in crime as a means to get money</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Người thất nghiệp có thể phạm tội như một cách để kiếm tiền</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• The unemployed need careers advice</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Những người không có việc làm cần được tư vấn thêm về nghề nghiệp</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Governments need to provide vocational courses and retraining</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Chính phủ cần hỗ trợ các khóa đào tạo nghề và đào tạo lại</span></div><br><div style=\"display:flex;font-weight:700;font-size:0.88rem;color:var(--primary);margin:8px 0 4px;\"><span style=\"flex:1;padding-right:10px;\">Positives of unemployment benefits</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-weight:400;font-size:0.8rem;color:var(--text-muted);font-style:italic;\">Ưu điểm của trợ cấp thất nghiệp Some governments pay unemployment benefits in order to help jobless people Một số chính phủ trợ cấp cho người thất nghiệp để giúp đỡ những người không có việc làm Unemployed people need financial support until they find a new job</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span data-vi=\"1\" style=\"flex:1;font-size:0.82rem;\">Người thất nghiệp cần hỗ trợ tài cính cho đến khi họ có việc làm</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• By claiming benefits they can continue to pay for their homes</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Bằng cách xin trợ cấp thất nghiệp họ có thể trả tiền thuê nhà</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• The benefits system helps to reduce poverty, homelessness and crime</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Trợ cấp thất nghiệp giúp giảm nghèo đói, vô gia cư và tội phạm</span></div><br><div style=\"display:flex;font-weight:700;font-size:0.88rem;color:var(--primary);margin:8px 0 4px;\"><span style=\"flex:1;padding-right:10px;\">Negatives of unemployment benefits</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-weight:400;font-size:0.8rem;color:var(--text-muted);font-style:italic;\">Nhược điểm của trợ cấp thất nghiệp Some people claim benefits rather than working</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span data-vi=\"1\" style=\"flex:1;font-size:0.82rem;\">Một số người xin trợ cấp thất nghiệp thay vì đi làm</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• They become dependent on the government</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Họ trở nên phụ thuộc vào chính phủ</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• They are not motivated to find a job</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Họ không có động lực để tìm việc</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• The benefits system is a burden on taxpayers</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Hệ thống trợ cấp là một gánh nặng đối với người nộp thuế</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• All citizens should work to earn a living and support themselves</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Mọi công dân phải làm việc kiếm sống và nuôi sống bản thân</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Receiving benefits affects people’s self esteem</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Nhận trợ cấp ảnh hưởng đến lòng tự trọng của mỗi người</span></div><br><div style=\"display:flex;font-weight:700;font-size:0.88rem;color:var(--primary);margin:8px 0 4px;\"><span style=\"flex:1;padding-right:10px;\">Work/Life Balance</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-weight:400;font-size:0.8rem;color:var(--text-muted);font-style:italic;\">Cân bằng giữa công việc và cuộc sống</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• It is important to achieve a balance between work time and leisure or family time</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Cần phải có sự cân bằng giữa công việc và giải trí hoặc thời gian dành cho gia đình</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Too much work can result in stress and poor health</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Làm việc nhiều quá có thể dẫn đến căng thẳng và sức khỏe yếu đi</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• “workaholics” may neglect their families and friends</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Những người nghiện việc sẽ sao nhãng gia đình và bạn bè</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• People need to take regular holidays</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Mọi người cần phải đi du lịch thường xuyên</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Nowadays, many people work part-time or have flexible working hours</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Ngày nay, nhiều người làm việc bán thời gian hoặc công việc linh hoạt</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Technology allow people to work from home</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Công nghệ cho phép mọi người có thể làm việc ở nhà</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Many companies provide childcare facilities</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Nhiều công ty cung cấp các thiết bị chăm sóc trẻ em</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• A good work/ life balance can raise job satisfaction</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Cân bằng công việc và cuộc sống sẽ tăng sự hài lòng trong công việc</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Happy, healthy workers are more productive</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Nhân viên khỏe mạnh, vui vẻ thì làm việc hiệu quả hơn</span></div><br><div style=\"display:flex;font-weight:700;font-size:0.88rem;color:var(--primary);margin:8px 0 4px;\"><span style=\"flex:1;padding-right:10px;\">Technology and work</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-weight:400;font-size:0.8rem;color:var(--text-muted);font-style:italic;\">Công nghệ và công việc</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Internet, fax and mobile phone technologies have revolutionized working life Internet, fax</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">và điện thoại đã làm thay đổi công việc</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Workers can communicate via email, online networks and video conferencing</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Người đi làm có thể giao tiếp với nhau thông qua thư điên tử, các mạng và hội thảo trực tuyến</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Technology can connect workers in different countries</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Công nghệ kết nối người đi làm ở nhiều quốc gia khác nhau</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• It gives people more freedom</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Công nghệ làm cho con người có nhiều tự do hơn</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• It can also save time and money</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Công nghệ cũng giúp tiết kiệm thời gian và tiền bạc</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Some people believe that offices could disappear in the future</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Một số người tin rằng trong tương lai văn phòng có thể sẽ biến mất</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Virtual online offices may replace them</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Các văn phòng ảo có thể sẽ thay thế các văn phòng hiện nay</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• TRANSPORT – GIAO</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">THÔNG</span></div></div>"},
  {id:"transport", icon:"🚌", label:"GIAO THÔNG", html:"<div style=\"font-size:0.85rem;line-height:1.6;\"><div style=\"display:flex;font-weight:700;font-size:0.88rem;color:var(--primary);margin:8px 0 4px;\"><span style=\"flex:1;padding-right:10px;\">Traffic problems</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-weight:400;font-size:0.8rem;color:var(--text-muted);font-style:italic;\">Các vấn đề giao thông</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Traffic congestion is caused by commuters travelling to work</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Tắc nghẽn giao thông gây ra bởi việc đi lại đến chỗ làm</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Most people live in the suburbs outside city centre</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Hầu hết mọi người sống ở ngoại ô xa trung tâm thành phố</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Commuters tend to travel at the same time of day</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Những người đi làm thường đi vào cùng một khung giờ trong ngày</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• They tend to travel alone</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Họ có xu hướng đi một mình</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• This causes traffic jams during the rush hour</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Điều này dẫn đến tắc nghẽn giao thông trong suốt giờ cao điểm</span></div><br><div style=\"display:flex;font-weight:700;font-size:0.88rem;color:var(--primary);margin:8px 0 4px;\"><span style=\"flex:1;padding-right:10px;\">Traffic solutions</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-weight:400;font-size:0.8rem;color:var(--text-muted);font-style:italic;\">Giải pháp cho vấn đề giao thông</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• In order to reduce traffic we should change our working habits</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Để giảm ách tắc giao thông, chúng ta cần thay đổi thói quen công việc The</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Internet can now be used to connect people</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Ngày nay chúng ta có thể dùng internet để kết nối mọi người</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• More people could work from home</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Có thể tăng số người làm việc tại nhà</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Meetings can be held as video conferences</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Cuộc họp có thể tổ chức qua video</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Workers could be given flexible timetables</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Người đi làm nên có thời gian biểu linh hoạt</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Another solution would be to tax drivers</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Một giải pháp khác là đánh thuế tài xế</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Workers should share their cars and travel together</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Người đi làm có thể đi chung xe với nhau</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Public transport needs to be reliable and efficient</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Giao thông công cộng phải tin cậy và hiệu quả hơn</span></div><br><div style=\"display:flex;font-weight:700;font-size:0.88rem;color:var(--primary);margin:8px 0 4px;\"><span style=\"flex:1;padding-right:10px;\">Positives of Public transport</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-weight:400;font-size:0.8rem;color:var(--text-muted);font-style:italic;\">Ưu điểm của giao thông công cộng We need to reduce our dependence on cars</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span data-vi=\"1\" style=\"flex:1;font-size:0.82rem;\">Chúng ta cần giảm lệ thuộc vào xe ô tô</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Parking a car can be extremely difficult in big cities</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Có thể rất khó tìm chỗ đỗ xe ở các thành phố lớn</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Well-designed transport systems are comfortable and convenient</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Hệ thống giao thông công cộng được thiết kế thuận tiện và thoải mái hơn</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Modern public transport can be fast and cheap</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Giao thông công cộng hiện đại có thể vừa nhanh vừa rẻ</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Public transport can help to reduce pollution in cities</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">thông công cộng có thể giảm ô nhiễm môi trường ở các thành phố</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Investment in buses and trains will ease traffic congestion</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Đầu tư vào xe buýt và tàu hỏa sẽ làm giảm ách tắc giao thông</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Buses can be given special lands to avoid traffic</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Xe buýt được đi vào làn đường riêng để giảm ách tắc giao thông</span></div><br><div style=\"display:flex;font-weight:700;font-size:0.88rem;color:var(--primary);margin:8px 0 4px;\"><span style=\"flex:1;padding-right:10px;\">Negatives of public transport</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-weight:400;font-size:0.8rem;color:var(--text-muted);font-style:italic;\">Bất lợi của giao thông công cộng Public transport if often slow and unreliable</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span data-vi=\"1\" style=\"flex:1;font-size:0.82rem;\">Giao thông công cộng thường chậm và không đáng tin cậy</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Buses are often dirty and crowded</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Xe buýt thường chậm và bẩn</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• People feel like “sardines in a can”</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Mọi người cảm thấy ngột ngạt, khó thở</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Cars are much more comfortable</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Đi bằng xe riêng thì thoải mái hơn</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• FAMILY – GIA</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">ĐÌNH</span></div></div>"},
  {id:"family", icon:"👨‍👩‍👧‍👦", label:"GIA ĐÌNH", html:"<div style=\"font-size:0.85rem;line-height:1.6;\"><div style=\"display:flex;font-weight:700;font-size:0.88rem;color:var(--primary);margin:8px 0 4px;\"><span style=\"flex:1;padding-right:10px;\">Family size</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-weight:400;font-size:0.8rem;color:var(--text-muted);font-style:italic;\">Kích thước gia đình</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Families in many countries are not as large as they used to be</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Ở nhiều quốc gia đình không đông như ngày xưa</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• We tend to live in small nuclear families rather than large extended families</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Chúng ta có xu hướng sống trong gia đình hạt nhân thay vì gia đình nhiều thế hệ</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Parents tend to have fewer children</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Bố mẹ có xu hướng đẻ ít con hơn</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Young children are no longer expected to work</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Trẻ nhỏ không còn phải đi làm</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Nowadays both parents often work</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Ngày nay thông thường bố mẹ đều đi làm</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• It costs so much to bring children up</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Ngày nay nuôi dưỡng con cái tốn kém hơn</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• It is more difficult to raise a large family</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Nuôi một gia đình đông con giờ khó khăn hơn nhiều</span></div><br><div style=\"display:flex;font-weight:700;font-size:0.88rem;color:var(--primary);margin:8px 0 4px;\"><span style=\"flex:1;padding-right:10px;\">Working parents</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-weight:400;font-size:0.8rem;color:var(--text-muted);font-style:italic;\">Cha mẹ bận công việc</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Children and their parents seem to be less close nowadays</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Ngày nay, cha mẹ và trẻ em dường như xa cách hơn</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Parents spend less time with their children</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Cha mẹ dành ít thời gian cho con cái hơn</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Women traditionally stayed at home to cook, clean and look after children</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Ngày xưa phụ nữ thường ở nhà nấu nướng, quét dọn và chăm con</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Nowadays both parents often work full time</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Ngày nay cả 2 cha mẹ đều đi làm toàn thời gian</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Children may be left alone, or with nannies or babysitters</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Trả em bị bỏ một mình hoặc ở cùng vú nuôi hoặc người trông trẻ</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Busy parents have less contact with their children</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Bố mẹ bận rộn ít giao tiếp với con cái hơn</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Many families no longer eat meals together</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Nhiều gia đình không còn ăn cùng nhau</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Children spend more time with friends or surfing the Internet</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Trẻ em dành nhiều thời gian với bạn bè hoặc lướt Web</span></div><br><div style=\"display:flex;font-weight:700;font-size:0.88rem;color:var(--primary);margin:8px 0 4px;\"><span style=\"flex:1;padding-right:10px;\">Negative effects on Children</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-weight:400;font-size:0.8rem;color:var(--text-muted);font-style:italic;\">Ảnh hưởng tiêu cực đến trẻ em The lack of closeness in families can have a negative effect on children Sự thiếu gần gũi trong gia đình có thể ảnh hưởng tiêu cực đến trẻ em Many parents have no idea how their children spend their time</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span data-vi=\"1\" style=\"flex:1;font-size:0.82rem;\">Nhiều bố mẹ không biết con cái dành thời gian để làm gì</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Friends, television and the Internet become the main influence on children’s behavior</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Bạn bè, ti vi và Internet có ảnh hướng chính đến cách cư xử của trẻ</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Teenagers are influenced by peer pressure</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Thiếu niên bị ảnh hưởng bởi áp lực bạn bè</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Some of them join gangs</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Một số thiếu niên tham gia vào các băng đảng</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Juvenile delinquency is on the increase</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Trẻ em phạm tội gia tăng</span></div><br><div style=\"display:flex;font-weight:700;font-size:0.88rem;color:var(--primary);margin:8px 0 4px;\"><span style=\"flex:1;padding-right:10px;\">Solution</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-weight:400;font-size:0.8rem;color:var(--text-muted);font-style:italic;\">Giải pháp</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Parents should be more involved with their children’s upbringing</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Bố mẹ nên quan tâm hơn đến việc nuôi dạy con</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Young people need positive role models</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Những người trẻ cần có những hình mẫu tích cực để noi theo</span></div><br><div style=\"display:flex;font-weight:700;font-size:0.88rem;color:var(--primary);margin:8px 0 4px;\"><span style=\"flex:1;padding-right:10px;\">Divorce</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-weight:400;font-size:0.8rem;color:var(--text-muted);font-style:italic;\">Ly dị</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• In the past, divorce was unacceptable</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Ngày xưa, ly dị là việc không thể chấp nhận</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• It was considered to be embarrassing for a family</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Ngày xưa ly dị là nỗi xấu hổ của gia đình</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• People stayed together for religious or family reasons</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Vợ chồng cùng nhau vì lý do tôn giáo hoặc gia đình</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Divorce is more socially acceptable nowadays</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Ngày này việc ly dị được xã hội chấp nhận</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• It has become much more common</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Nó trở nên phổ biến hơn</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Divorce can be extremely stressful</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Ly dị có thể cực kỳ căng thẳng</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Lone parents may face financial difficulties</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Bố mẹ đơn thân có thể gặp nhiều vấn đề về tài chính</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Many single parents have to rely on benefits paid by the state</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Nhiều bố mẹ đơn thân cần dựa vào trợ cấp của chính phủ</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Divorce can have a negative effect on children</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Ly dị có ảnh hưởng tiêu cực đến trẻ em</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Children from single-parent families are more likely to get lower grades or drop out of school. Con</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">cái của bố mẹ đơn thân có khả năng bị điểm kém ở trường học hoặc bỏ học The</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• rise in divorce rates may be connected to some social problems</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Tỷ lệ ly dị tăng có thể lên quan đến một số vấn đề của xã hội 5. Immigration - Di cư</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Some people move to another countries in search of a better life</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Một số người di cư sang quốc gia khác để tìm kiếm một cuộc sống tốt hơn</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Many immigrants come from less developed countries</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Nhiều người nhập cư đến từ các quốc gia kém phát triển</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Richer, industrialized countries may offer opportunities for employment</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Những nước giàu, nước công nghiệp hóa có thể có cơ hội việc làm tốt hơn</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Free healthcare and schooling are available in some developed countries</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Ở quốc gia phát triển y tế và giáo dục được miễn phí</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Other people migrate to a foreign country to improve their academic qualifications</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Nhiều người khác di cư để cải thiện kỹ năng</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Positives of immigration and multi-cultural societies -</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Ưu điểm của nhập cư và xã hội đa văn hóa</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• From an economic perspective, immigration can be extremely positive</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Từ góc độ kinh tế, nhập cư mang tính chất tích cực</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Many immigrants have skills that are needed in the country they move to</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Nhiều người nhập cư có kỹ năng cần thiết ở quốc gia nhập cư</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Immigrants who find work contribute to the economy of their new country</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Những người nhập cư tìm công việc có đóng góp cho nên kinh tế của đất nước mới</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Many immigrants send money home to help family members</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Nhiều người nhập cư gửi tiền về nhà để giúp đỡ gia đình</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Immigration also creates cultural diversity</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Nhập cư cũng tạo sự đa dạng về văn hóa</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• People of many different nationalities learn to live together</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Mọi người mang nhiều quốc tịch khác nhau học cách sống cùng nhau</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• This can help people to become more open-minded and tolerant</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Điều đó giúp họ trở nên cởi mở và khoan dung hơn</span></div></div>"},
  {id:"immigration", icon:"🌍", label:"DI CƯ", html:"<div style=\"font-size:0.85rem;line-height:1.6;\"><div style=\"display:flex;font-weight:700;font-size:0.88rem;color:var(--primary);margin:8px 0 4px;\"><span style=\"flex:1;padding-right:10px;\">Negatives of immigration</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-weight:400;font-size:0.8rem;color:var(--text-muted);font-style:italic;\">Nhược điểm của nhập cư</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Some people believe that immigrants take jobs that should go to local people</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Một số người tin rằng người nhập cư lấy đi công việc mà nhẽ ra dành cho người bản địa</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Some immigrant workers work longer hours for less money</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Một số người nhập cư làm việc nhiều giờ hơn nhưng kiếm được ít tiền hơn</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Companies might pay lower salaries to immigrant workers</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Nhiều công ty có thể trả lương thấp hơn cho lao động nhập cư</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Unemployment rates could rise if there are too many immigrants</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Tỷ lệ thất nghiệp có thể tăng cao nếu có quá nhiều người nhập cư</span></div><br><div style=\"display:flex;font-weight:700;font-size:0.88rem;color:var(--primary);margin:8px 0 4px;\"><span style=\"flex:1;padding-right:10px;\">Opinions about immigration</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-weight:400;font-size:0.8rem;color:var(--text-muted);font-style:italic;\">Quan điểm về nhập cư</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Immigration can help the economy of a country</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Nhập cư có thể giúp ích cho một nền kinh tế</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• It can create multi-cultural societies</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Nhập cư tạo ra xã hội đa văn hóa</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• However, immigration needs to be controlled</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Tuy nhiên, nhập cư cần phải được kiểm soát</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• In many countries, immigrants need visas or work permit</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Ở nhiều quốc gia, người nhập cư phải xin visa và giấy phép làm việc</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Governments should stop companies from exploiting immigrant workers</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Chính phủ nên đóng cửa các công ty khai thác công nhân nhập cư</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Foreign and local workers should have the right to equal pay and conditions</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Công nhân nước ngoài và công nhân địa phương nên có quyền được hưởng lương và chế độ như nhau</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• HEALTHY DIET –</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">CHẾ ĐỘ ĂN LÀNH MẠNH</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• The human body requires a balanced diet</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Cơ thể con người cần chế độ ăn uống cân bằng</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• An unhealthy diet can cause various health problems</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Một chế độ ăn không lành mạnh có thể dẫn đến nhiều bệnh tật khác</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• nhau Obesity, diabetes and heart disease are on the increase</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Béo phì, tiểu đường, bệnh tim mạch ngày càng gia tăng</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Many people nowadays rely on fast food or pre-prepared meals</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Ngày nay, nhiều người phụ thuộc vào thức ăn nhanh hoặc thức ăn được chế biến sẵn</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• These foods often contain too much fat, salt and sugar</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Những đồ ăn này thường chưa nhiều chất béo, muối và đường</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• They are cheap to buy and very easy to prepare</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Những đồ ăn này thường rẻ và dễ chuẩn bị</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Many young people have grown up on a diet of convenience foods</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Nhiều người trẻ lớn lên bằng những đồ ăn tiện lợi</span></div></div>"},
  {id:"diet", icon:"🥗", label:"SỨC KHỎE", html:"<div style=\"font-size:0.85rem;line-height:1.6;\"><div style=\"display:flex;font-weight:700;font-size:0.88rem;color:var(--primary);margin:8px 0 4px;\"><span style=\"flex:1;padding-right:10px;\">Exercise</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-weight:400;font-size:0.8rem;color:var(--text-muted);font-style:italic;\">Tập thể dục</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Regular exercise is essential in maintaining a healthy body</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Tập thể dục thường xuyên rất cần thiết để duy trì một cơ thể khỏe mạnh</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Exercise burns calories and helps to build healthy bones and muscles</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Tập thể dục đốt cháy calo và giúp xương và cơ thể chắc khỏe</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Doctors advise exercising at least three times a week for 20 minutes</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Bác sỹ khuyên nên tập thể dục ít nhất 3 lần/tuần, mỗi lần 20 phút</span></div><br><div style=\"display:flex;font-weight:700;font-size:0.88rem;color:var(--primary);margin:8px 0 4px;\"><span style=\"flex:1;padding-right:10px;\">Government’s Role</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-weight:400;font-size:0.8rem;color:var(--text-muted);font-style:italic;\">Vai trò của chính phủ</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Governments have a significant role to play in reducing obesity</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Chính phủ có vai trò quan trọng trong việc giảm tỷ lệ béo phì</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• More and more people, including young children are seriously overweight</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Ngày càng nhiều người, trong đó có trẻ em thừa cân nghiêm trọng</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• They are at risk of heart disease and diabetes</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Họ có nguy cơ mắc bệnh tim và tiểu đường</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• This situation will increase the burden on hospitals and taxpayers</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Tình trạng này làm gia tăng gánh nặng lên bệnh viện và người trả thuế</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Hospitals rely on the government for money and resources</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Bệnh viện phụ thuộc vào ngân sách nhà nước và nhân lực</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Governments should promote a healthy diet and regular exercise</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Chính phủ nên cần khuyến khích ăn uống lành mạnh và tập thể dục thường xuyên</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• There should be more time for sports on school timetables</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Thời khóa biểu tại các trường học nên dành nhiều thời gian cho các môn thể thao</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Unhealthy junk food should be banned from school menus</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Các thức ăn không tốt cho sức khỏe nên loại khỏi thức ăn của nhà trường</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• People need information about what foods contain</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Mọi người cần biết rõ về thành phần thức ăn</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Food packaging must show the food’s nutritional content</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Bao bì sản phẩm phải ghi rõ thành phần dinh dưỡng của đồ ăn 7. STRESS – CĂNG THẲNG</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Modern lifestyles are increasingly stressful</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Cuộc sống hiện đại ngày càng nhiều áp lực</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• People work long hours with strict deadlines</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Con người phải làm việc nhiều giờ với thời hạn nghiêm ngặt</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Our busy lifestyles mean we have less time to relax</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Cuộc sống bận rộn đồng nghĩa với việc chúng ta có ít thời gian để nghỉ ngơi</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Unemployment is a major cause of stress</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Thất nghiệp là nguyên nhân chính dẫn đến căng thẳng</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Children may be affected by their parents’ relationship problems</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Trẻ em có thể bị ảnh hưởng khi bố mẹ xích mích</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Tests and exams can also cause stress</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Kiểm tra, thi cử cũng có thể gây ra căng thẳng</span></div></div>"},
  {id:"stress", icon:"😰", label:"CĂNG THẢNG", html:"<div style=\"font-size:0.85rem;line-height:1.6;\"><div style=\"display:flex;font-weight:700;font-size:0.88rem;color:var(--primary);margin:8px 0 4px;\"><span style=\"flex:1;padding-right:10px;\">How to reduce stress</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-weight:400;font-size:0.8rem;color:var(--text-muted);font-style:italic;\">Làm thế nào để giảm cẳng thẳng</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Stress can be reduced by taking regular exercise and eating a healthy diet</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Có thể giảm căng thẳng bằng cách tập thể dục thường xuyên và ăn uống lành mạnh</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• It is also important to get sufficient sleep and make leisure time a priority</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Ngủ đủ giấc và ưu tiên thời gian nghỉ ngơi cũng rất quan trọng</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• People should work less overtime and take regular holidays</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Mọi người cần tránh đi làm quá giờ và đi du lịch thường xuyên</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Schools have started to employ psychologists</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Trường học cần có các chuyên gia tâm lý</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• They can offer emotional support to students</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Họ có thể giúp sinh viên trong các vấn đề về tình cảm</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• They can help students to cope with exam stress</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Họ có thể giúp sinh viên vượt qua căng thẳng 8. CITIES – THÀNH PHỐ</span></div></div>"},
  {id:"cities", icon:"🏙️", label:"THÀNH PHỐ", html:"<div style=\"font-size:0.85rem;line-height:1.6;\"><div style=\"display:flex;font-weight:700;font-size:0.88rem;color:var(--primary);margin:8px 0 4px;\"><span style=\"flex:1;padding-right:10px;\">Reasons for urbanization/migration to big cities</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-weight:400;font-size:0.8rem;color:var(--text-muted);font-style:italic;\">Lý do của việc đô thị hóa/di cứ đến thành phố</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• People move to cities in search of job opportunities or better education</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Người dân lên thành phố để tìm cơ hội việc làm hoặc giáo dục tốt hơn</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Cities offer a higher standard of living</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Mức sống ở thành phố cao hơn</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Entertainment facilities like the cinemas and amusement parks are often nearby Khu vui</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">chơi giải trí như rạp chiếu phim, công viên thường gần hơn</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• People move to cities from the countryside because traditional activities like farming need fewer workers nowadays</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Người dân nông thôn lên thành phố vì ngày nay các nghề truyền thống như nghề nông cần ít nhân công hơn.</span></div><br><div style=\"display:flex;font-weight:700;font-size:0.88rem;color:var(--primary);margin:8px 0 4px;\"><span style=\"flex:1;padding-right:10px;\">Negatives of city life/Problems of city life</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-weight:400;font-size:0.8rem;color:var(--text-muted);font-style:italic;\">Những bất lợi của cuộc sống ở thành phố/những vấn đề khi sống ở thành phố</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;\">• 8.2.1 Social problems</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Life in cities can be extremely stressful.</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Cuộc sống ở thành phố có thể rất căng thẳng</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• The cost of living is higher than in rural areas</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Chi phí sinh hoạt cao hơn ở nông thôn</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Housing is usually much more expensive</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Nhà cửa thường đắt đỏ hơn nhiều</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• unemployment rate is often high. Many people do not manage to find work</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Tỷ lệ thất nghiệp thường cao hơn. Nhiều người không tìm được việc làm</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Many unemployed commit crimes as a mean to earn money</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Nhiều người thất nghiệp trở nên cướp giật</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Traffic congestion is a big problem. People suffer from standstill traffic during rush hours.</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Tắc nghẽn giao thông là vấn đề lớn. Mọi người phải chịu cảnh đứng im trong suốt giờ cao điểm</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Cities lack a sense of community</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Ở thành phố thiếu tính cộng đồng</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• People do not even know their neighbor</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Mọi người thậm chí không biết hàng xóm</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Environmental problems in urban areas:</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Các vấn đề về môi trường ở khu vực thành thị</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• People in urban areas often have pollution of air, water and noise</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Cư dân đô thị thường phải chịu cảnh ô nhiễm không khí, nước và tiếng ồn.</span></div><br><div style=\"display:flex;font-weight:700;font-size:0.88rem;color:var(--primary);margin:8px 0 4px;\"><span style=\"flex:1;padding-right:10px;\">Pedestrian Areas</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-weight:400;font-size:0.8rem;color:var(--text-muted);font-style:italic;\">Khu dành cho người đi bộ</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Pedestrian zones in city centre can improve the local environment Khu</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">vực dành cho người đi bộ ở trung tâm thành phố sẽ cải thiện được môi trường.</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Banning cars encourages people to walk or cycle</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Cấm xe hơi, khuyến khích mọi người đi bộ hoặc xe đạp</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Many European cities have built bicycle lanes</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Một số thành phố ở châu âu đã xây dựng cho xe đạp</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Dependence on cars is linked to health problems like obesity</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Những người phụ thuộc vào xe hơi có nguy cơ về vấn đề sức khỏe như béo phì</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• People who walk or cycle regularly are generally healthier</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Những người đi bộ hoặc xe đạp thường xuyên thường có sức khỏe tốt hơn</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Pedestrian areas are safer and more attractive for both residents and tourists Khu</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">vực dành cho người đi bộ thường an toàn và thu hút người dân cũng như khác du lịch. 9. EDUCATION – GIÁO DỤC</span></div></div>"},
  {id:"education", icon:"🎓", label:"GIÁO DỤC", html:"<div style=\"font-size:0.85rem;line-height:1.6;\"><div style=\"display:flex;font-weight:700;font-size:0.88rem;color:var(--primary);margin:8px 0 4px;\"><span style=\"flex:1;padding-right:10px;\">Benefits of education</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-weight:400;font-size:0.8rem;color:var(--text-muted);font-style:italic;\">Lợi ích của giáo dục</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Education gives people knowledge and skills</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Giáo dục cung cấp kiến thức và kỹ năng cho con người</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• People with qualification are more likely to find work</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Những người có bằng cấp có nhiều cơ hội việc làm hơn</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• They can earn a higher salary</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Họ có thể kiếm được mức lương cao hơn</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• They can contribute positively to society</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Họ có thể có những đóng góp tích cực hơn cho xã hội</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Schools aim to teach young people moral values such as tolerance and sharing</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Trường học dạy học sinh về giá trị đạo đức như lòng khoan dung và sự chia sẻ</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Schools prepare children to be members of a society</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Trường học chuẩn bị hành trang cho trẻ trở thành công dân của xã hội</span></div><br><div style=\"display:flex;font-weight:700;font-size:0.88rem;color:var(--primary);margin:8px 0 4px;\"><span style=\"flex:1;padding-right:10px;\">Benefits of studying abroad</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-weight:400;font-size:0.8rem;color:var(--text-muted);font-style:italic;\">Lợi ích của việc du học</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Foreign institutions may offer better courses</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Các trường nước ngoài có thể có nhiều khóa học tốt hơn trong nước</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Many students want to attend a prestigious university</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Nhiều sinh viên muốn tham gia học ở trường đại học danh tiếng</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• The best universities employ teachers who are experts in their fields</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Những trường đại học tốt có đội ngũ giảng viên là những chuyên gia đầu ngành</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Qualifications gained abroad can open the door to better job opportunities</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Bằng cấp ở nước ngoài có thể mở ra nhiều cơ hội việc làm tốt hơn</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Living abroad can broaden students’ horizons</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Sống ở nước ngoài có thể mở rộng chân trời mới cho sinh viên</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Overseas students are exposed to different cultures and customs.</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">học sinh được mở mang tiếp xúc với các nên văn hóa và phong tục khác</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• nhau They become more independent</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Họ sẽ trở nên độc lập hơn</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• They are responsible for cooking, cleaning and paying bills</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Họ phải tự nấu nướng, giặt giũ và trả tiền sinh hoạt phí/tiền hóa đơn</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• They will learn a foreign language</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Họ sẽ học được ngoại ngữ</span></div><br><div style=\"display:flex;font-weight:700;font-size:0.88rem;color:var(--primary);margin:8px 0 4px;\"><span style=\"flex:1;padding-right:10px;\">Drawback of studying abroad</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-weight:400;font-size:0.8rem;color:var(--text-muted);font-style:italic;\">Bất lợi của việc đi du học</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Living and studying abroad can be difficult</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Sống và học tập ở nước ngoài có thể gặp khó khăn</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Students have problems with paperwork such as visa applications Sinh</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">viên có thể gặp vấn đề về các giấy tờ liên quan như</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• visa The language barrier can be a problem</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Rào cản ngôn ngữ có thể là một vấn đề</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Students have to find accommodation and pay bills</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Sinh viên phải tiềm chỗ cư trú và thanh toán sinh hoạt phí</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Studying in a foreign language is challenging</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Học tập với một ngôn ngữ khác là một thách thức</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Living alone in an unfamiliar culture can cause homesickness</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Sống một mình ở nền văn hóa khác có thể khiến nhớ nhà</span></div><br><div style=\"display:flex;font-weight:700;font-size:0.88rem;color:var(--primary);margin:8px 0 4px;\"><span style=\"flex:1;padding-right:10px;\">Technology in Education</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-weight:400;font-size:0.8rem;color:var(--text-muted);font-style:italic;\">Công nghệ trong giáo dục</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;\">• 9.4.1 Advantages of technology in Education</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Technology is a powerful tool to engage students</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Công nghệ là một công cụ hữu ích gây hứng thú cho sinh viên</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Technology can make lessons much more interesting</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Công nghệ có thể khiến các bài học trở nên hấp dẫn hơn</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Students can do research using online resources</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Sinh viên có thể tìm kiếm thông tin trên mạng</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Students can study at their own place</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Sinh viên có thể nghiên cứu tại nhà</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Adults can take distance learning courses</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Người lớn có thể tham gia các khóa học từ xa</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Students can study whenever and wherever they want</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Sinh viên có thể học bất cứ khi nào, bất cứ nơi đâu họ muốn</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Students also learn skills which are useful for their future jobs</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Sinh viên cũng học được các kỹ năng hữu ích cho công việc của họ sau này</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• For example, they learn to write reports using a word processor</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Ví dụ, họ có thể học viết báo cáo sử dụng các phần mềm soạn văn bản</span></div><br><div style=\"display:flex;font-weight:700;font-size:0.88rem;color:var(--primary);margin:8px 0 4px;\"><span style=\"flex:1;padding-right:10px;\">Disadvantages of Technology in Education</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-weight:400;font-size:0.8rem;color:var(--text-muted);font-style:italic;\">Bất lợi của công nghệ trong giáo dục</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• People rely too much on computers</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Con người phụ thuộc quá nhiều vào máy tính</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Young learners do not become proficient in some basic skills</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Những người trẻ không sử dụng thành thạo một số kỹ năng cơ bản</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• They use word processors and spelling may suffer</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Họ thường sử dụng máy xử lý văn bản và gặp lỗi về chính tả</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• People should be able to write a letter by hand</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Mọi người nên viết thư bằng tay</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Technology is no substitute for a real teacher</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Công nghệ không thể thay thế được giáo viên</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Learners need a structured course</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Người học cần một khóa học cấu trúc bài bản</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• An experienced teacher knows what materials to choose</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Giáo viên có kinh nghiệm biết cách lựa chọn tài liệu</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Computers are expensive to maintain and can be unreliable</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Mất nhiều kinh phí để duy trì máy tính và máy tính không đáng tin cậy</span></div><br><div style=\"display:flex;font-weight:700;font-size:0.88rem;color:var(--primary);margin:8px 0 4px;\"><span style=\"flex:1;padding-right:10px;\">Opinion on Technology in Education</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-weight:400;font-size:0.8rem;color:var(--text-muted);font-style:italic;\">Quan điểm về công nghệ trong giáo dục</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Institutions should supplement traditional teaching with the use of technology</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Các trường học nên áp dụng phương pháp kết hợp cách dạy truyền thống với sử dụng công nghệ thông tin</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Technology is part of everyday life</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Công nghệ là một phần của cuộc sống ngày nay</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• It can enhance a teacher’s lessons</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Công nghệ có thể hỗ trợ bài giảng của giáo viên</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Students can use online resources to help with homework</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Sinh viên có thể sử dụng tài liệu trực tuyến để giúp hoàn thiện bài tập về nhà</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Students must still learn to write by hand</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Sinh viên vẫn phải viết bằng tay</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• They should still use traditional sources of information such as books</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Sinh viên vẫn nên sử dụng các nguồn thông tin truyền thống như sách 24</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Education in Developing countries -</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Giáo dục ở các nước đang phát triển</span></div><br><div style=\"display:flex;font-weight:700;font-size:0.88rem;color:var(--primary);margin:8px 0 4px;\"><span style=\"flex:1;padding-right:10px;\">Problems of education in developing countries</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-weight:400;font-size:0.8rem;color:var(--text-muted);font-style:italic;\">Vấn đề của giáo dục ở các nước đang phát triển</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Children often have to work from an early age</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Trẻ con thường phải làm việc khi còn khá nhỏ tuổi</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• There are no schools in many areas</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Nhiều nơi chưa có trường học</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Families do not have access to books or computers</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Nhiều gia đình không có sách vở hoặc máy tính</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Literacy rates are often low</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Tỷ lệ biết chữ thường thấp</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• People in developing countries need knowledge and skills</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Người dân ở các nước đang phát triển cần có kiến thức và kỹ năng</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Education is the key to improving the economy of these countries</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Giáo dục là chìa khóa để cải thiện kinh tế ở các nước đang phát triển</span></div><br><div style=\"display:flex;font-weight:700;font-size:0.88rem;color:var(--primary);margin:8px 0 4px;\"><span style=\"flex:1;padding-right:10px;\">Solutions to education in developing countries</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-weight:400;font-size:0.8rem;color:var(--text-muted);font-style:italic;\">Giải pháp giáo dục ở các nước đang phát triển</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Developed countries could help developing nations by providing money</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Các nước phát triển có thể giúp nước đang phát triển bằng cách cung cấp tiền</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• They could invest in schools and technology</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Họ có thể đầu tư vào trường học và công nghệ</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• They could supply the funds to build schools and pay for teachers</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Họ có thể cung ứng tiền xây dựng trường học và thuê giáo viên dạy</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Children need to have access to free schooling</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Trẻ em cần được học tập miễn phí</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Computer equipment could be donated</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Quyên góp máy tính cho các trường</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Internet can expose students to a world of knowledge and information Internet</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">giúp sinh viên tiếp cận với nguồn kiến thức và thông tin của nhân loại</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Governments should make education compulsory for all children</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Chính phủ cần phải có môi trường giáo dục bắt buộc đối với trẻ em</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• They should encourage parents to send their children to school</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Chính phủ nên khuyến khích cha mẹ cho trẻ đi học</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Governments of developed and developing countries must work together</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Chính phủ các nước phát triển và các nước đang phát triển cần phải hợp tác với nhau</span></div><br><div style=\"display:flex;font-weight:700;font-size:0.88rem;color:var(--primary);margin:8px 0 4px;\"><span style=\"flex:1;padding-right:10px;\">Advantages of higher education</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-weight:400;font-size:0.8rem;color:var(--text-muted);font-style:italic;\">Lợi ích của giáo dục đại học</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• There are many benefits to going to university</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Có nhiều lợi ích của việc học đại học</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• A degree can open the door to better employment prospects</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Bằng cấp có thể mở cánh cảnh cửa cơ hội nghề nghiệp tốt hơn</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Economies are becoming increasingly knowledge-based</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Nền kinh tế đang ngày càng phụ thuộc và kiến thức</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Most jobs require specific knowledge and skills</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Hầu hết công việc đều yêu cầu kiến thức và kỹ năng nhất định</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Skilled workers are needed for sectors such as information technology and engineering</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Những người có trình độ được tuyển dụng cho các lĩnh vực như công nghệ thông tin và kỹ sư</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Repetitive manual jobs are now done by machine</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Ngày nay, những công việc thủ công lặp đi lặp lại có thể thay thế bằng máy móc</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Many factories have moved to developing countries</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Nhiều nhà máy được xây dựng ở các nước đang phát triển</span></div><br><div style=\"display:flex;font-weight:700;font-size:0.88rem;color:var(--primary);margin:8px 0 4px;\"><span style=\"flex:1;padding-right:10px;\">Disadvantages of higher education</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-weight:400;font-size:0.8rem;color:var(--text-muted);font-style:italic;\">Bất lợi của giáo dục đại học</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• A healthy economy needs a wide range of workers</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Một nền kinh tế khỏe mạnh cần nhiều nguồn nhân lực khác nhau</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Some manual workers will always be needed</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Một số công nhân lao động vẫn luôn cần thiết</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• A university degree is not necessary for many service professions</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Bằng đại học không cần thiết cho một số ngành nghề dịch vụ</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Practical training is more important in some industries</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Ở một số ngành nghề, kinh nghiệm thực tế quan trong hơn</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• In the UK, for example, there is currently a shortage of plumbers. Their services are therefore becoming more and more expensive.</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Một ví dụ ở nước Anh, hiện nay đang thiếu thợ sửa ống nước. Vì thế, dịch vụ này ngày càng trở nên đắt đỏ</span></div><br><div style=\"display:flex;font-weight:700;font-size:0.88rem;color:var(--primary);margin:8px 0 4px;\"><span style=\"flex:1;padding-right:10px;\">Causes of bad behavior in schools</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-weight:400;font-size:0.8rem;color:var(--text-muted);font-style:italic;\">Nguyên nhân học sinh có hành vi xấu</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Bad behavior is due to a lack of structure and discipline</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Hành vi xấu do thiếu tổ chức và kỷ luật</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• There are too many children in some classes</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Một số lớp có sĩ số quá đông</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Large classes are difficult to manage</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Rất khó quản lý lớp đông</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• May disruptive students come from an unstable family background</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Nhiều học sinh hư là con em của gia đình bất ổn</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Other parents are too lenient and spoil their children</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Nhiều bố mẹ thì hiền quá nên làm con hư</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Some children are used to getting whatever they want</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Một số trẻ quen với việc thích gì được nấy</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Schools can do very little if they are not supported by parents</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Trường học hầu như không giúp ích gì nhiều nếu như phụ huynh học sinh không ủng hộ9.8</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;\">• Solutions to bad behavior in schools</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Schools need a clear code of conduct</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Trường học cần phải có nguyên tắc rõ ràng</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Schools need a clear set of rules about behavior</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Trường học phải có quy tắc ứng xử rõ ràng</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• They need to create a positive working atmosphere</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Trường học cần tạo môi trường học tập tích cực</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Teachers must have the power to punish disruptive students</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Giáo viên phải có quyền phạt những học sinh hư</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Schools should remove difficult children from lessons</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Trường học nên đuổi những em học sinh cứng đầu ra khỏi lớp</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Schools need to work closely with parents</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Trường học nên kết hợp chặt chẽ với phụ huynh</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Discipline could be lacking at home</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Có thể môi trường ở nhà không đủ kỉ luật</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Parents must support the school rules</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Phụ huynh cần ủng hộ các quy tắc của trường</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• They should take responsibility for their children’s behavior</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Họ cần có trách nhiệm với hành vi của con cái</span></div></div>"},
  {id:"language", icon:"🗣️", label:"NGÔN NGỮ", html:"<div style=\"font-size:0.85rem;line-height:1.6;\"><div style=\"display:flex;font-weight:700;font-size:0.88rem;color:var(--primary);margin:8px 0 4px;\"><span style=\"flex:1;padding-right:10px;\">Positive of English as an international language</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-weight:400;font-size:0.8rem;color:var(--text-muted);font-style:italic;\">Ưu điểm khi sử dụng tiếng anh như một ngôn ngữ quốc tế</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• English is widely used around the world</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Tiếng anh được sử dụng rộng rãi trên toàn thế giới</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• It is becoming a global second language</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Tiếng anh trở thành ngôn ngữ thứ 2 trên toàn cầu</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• It is the dominant language of technology, science and international business</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Nó là ngôn ngữ phổ biến trong lĩnh vực khoa học, công nghệ và kinh doanh quốc tế</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• International business meetings are regularly held in English</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Các cuộc họp trong kinh doanh quốc tế thường bằng tiếng Anh</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• The most important textbooks and journals are published in English</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Hầu hết những sách và tạp chí quan trọng được xuất bản bằng tiếng Anh The</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• ability to speak English is a necessary skill in the modern world</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Có thể nói tiếng Anh là một kỹ năng cần thiết trong thế giới hiện đại</span></div><br><div style=\"display:flex;font-weight:700;font-size:0.88rem;color:var(--primary);margin:8px 0 4px;\"><span style=\"flex:1;padding-right:10px;\">Negative of English as an International Language</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-weight:400;font-size:0.8rem;color:var(--text-muted);font-style:italic;\">Nhược điểm khi sử dụng tiếng Anh như một ngôn ngữ quốc tế</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• If one language is dominant, other languages may disappear</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Nếu một ngôn ngữ phổ biển thì các ngôn ngữ khác có thể biến mất</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• The dominant language brings its own culture</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Ngôn ngữ phổ biến sẽ mang theo nền văn hóa mới</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• American culture has become popular around the world</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Văn hóa Mỹ đã trở nên nổi tiếng trên toàn cầu</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Other cultures may be damaged</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Các nền văn hóa khác có thể sẽ bị hủy</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• As an alternative to English, a new global language could be invented</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Để thay tiếng Anh, một ngôn ngữ toàn cầu mới có thể được phát minh</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• It would have no nationality or culture attached to it</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Nó sẽ không gắn với quốc tịch hay nền văn hóa</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• This could help to promote international peace and understanding</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Điều đó giúp tăng cường hòa bình thế giới và hiểu biết lẫn nhau</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Esperanto is an example of a language that was invented with this aim</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Esperanto là một ví dụ về ngôn ngữ được phát minh vì mục đích này 11. ADVERTISING – QUẢNG CÁO</span></div></div>"},
  {id:"advertising", icon:"📢", label:"QUẢNG CÁO", html:"<div style=\"font-size:0.85rem;line-height:1.6;\"><div style=\"display:flex;font-weight:700;font-size:0.88rem;color:var(--primary);margin:8px 0 4px;\"><span style=\"flex:1;padding-right:10px;\">Negatives of Advertising</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-weight:400;font-size:0.8rem;color:var(--text-muted);font-style:italic;\">Những bất cập của quảng cáo</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Advertising manipulates people</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Quảng cáo lôi kéo người tiêu dùng</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• It aims to persuade people that buying a product will make them happier</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Quảng cáo nhằm mục đích thuyết phục mọi người rằng mua sản phẩm sẽ làm cho họ hạnh phúc hơn.</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Advertisers focus on selling a brand image</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Nhà quảng cáo tập trung vào bán thương hiệu</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• They use glamorous, successful people</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Họ mời những người có sức thu hút, những người thành đạt</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• We now live in a consumer culture</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Ngày nay, chúng ta đang sống trong nền văn hóa tiêu thụ</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• We are persuaded to follow the latest trend</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Chúng ta đang bị thuyết phục để theo xu thế mới nhất</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• We are encouraged to associate certain brands with a higher status</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Chúng ta được khuyến khích để gắn mác thương hiệu nhất định với địa vị cao nhât</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Advertisers often aim their marketing at children</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Nhà quảng cáo thường hướng mục đích tiếp thị đến trẻ em</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Children can easily be influenced by advertisements.</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Trẻ em thường dễ bị ảnh hưởng bởi hình thức quảng cáo</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Children put pressure on parents to buy them things</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Trẻ em gây áp lực với bố mẹ để mua quà cho chúng.</span></div><br><div style=\"display:flex;font-weight:700;font-size:0.88rem;color:var(--primary);margin:8px 0 4px;\"><span style=\"flex:1;padding-right:10px;\">Positives of Advertising</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-weight:400;font-size:0.8rem;color:var(--text-muted);font-style:italic;\">Ưu điểm của quảng cáo</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Advertising is a key part of modern business</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Quảng cáo là một phần quan trọng của nền kinh tế hiện đại</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Companies need to tell customers about their products</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Các công ty cần giới thiệu sản phẩm cho khách hàng</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Advertisements inform us about the choices we have</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Quảng cáo giới thiệu cho chúng ta biết về các sản phẩm mà chúng ta có thể chọn</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Advertising is a creative industry that employs many people</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Quảng cáo là một nền công nghiệp sáng tạo, nó cung cấp việc làm cho nhiều người</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Without advertising we would have less choice</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Không có quảng cáo, chúng ta sẽ có ít lựa chọn</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Without advertising there would be higher unemployment</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Không có quảng cáo số lượng người thất nghiệp nhiều hơn</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Advertising is a form of modern art</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Quảng cáo là một hình thức nghệ thuật hiện đại</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• People enjoy adverts</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Mọi người thích xem quảng cáo</span></div><br><div style=\"display:flex;font-weight:700;font-size:0.88rem;color:var(--primary);margin:8px 0 4px;\"><span style=\"flex:1;padding-right:10px;\">Opinions about advertising</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-weight:400;font-size:0.8rem;color:var(--text-muted);font-style:italic;\">Quan điểm về quảng cáo</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Advertising should be regulated</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Quảng cáo nên được quản lý</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Advertising aimed at children should be controlled or even banned</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Quảng cáo hướng đến đối tượng trẻ nên được quản lý, thậm chí cấm</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Unhealthy foods should not be marketed in a way that attracts children</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Đồ ăn không lành mạnh không nên quảng cáo theo cách thức lôi cuốn trẻ em</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Products that can be risk to healthy should display warnings</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Các sản phẩm tiềm ẩn nguy cơ gây hại đối với sức khỏe nên có hình ảnh cảnh báo đi kèm</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• In some countries it is illegal to advertise cigarettes on television</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Ở một số nước, quảng cáo thuốc lá trên ti vi là vi phạm pháp luật</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Warnings must be displayed on cigarette packets</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Cảnh báo phải được in trên bao thuốc lá</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• However, advertising is necessary in free market economies</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Tuy nhiên, quảng cáo là rất cần thiết trong nền kinh tế thị trường</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• It creates demand for products</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Nó tạo ra nhu cầu đối với sản phẩm</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Governments should only censor false information or products that are harmful</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Chính phủ chỉ nên kiểm duyệt thông tin sai hoặc các sản phẩm gây hại 12. ENVIRONMENT – MÔI TRƯỜNG</span></div></div>"},
  {id:"environment", icon:"🌿", label:"MÔI TRƯỜNG", html:"<div style=\"font-size:0.85rem;line-height:1.6;\"><div style=\"display:flex;font-weight:700;font-size:0.88rem;color:var(--primary);margin:8px 0 4px;\"><span style=\"flex:1;padding-right:10px;\">Global warming</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-weight:400;font-size:0.8rem;color:var(--text-muted);font-style:italic;\">Trái đất nóng lên</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Gases such as carbon dioxide trap heat from the sun</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Các loại khí như CO2 giữ nhiệt mặt trời</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• This causes global temperatures to rise</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Điều này làm tăng nhiệt độ trái đất</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• This process is known as the greenhouse effect</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Quá trình này được gọi là hiệu ứng nhà kính</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Human activity is a major factor in the rise of the greenhouse gases</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Hoạt động của con người là nguyên nhân chính gây tăng hiệu ứng nhà kính</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Factories and vehicles produce emissions and exhaust fumes</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Nhà máy và xe cộ xả chất thải và khí thái</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Many developing countries are becoming industrialized</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Nhiều quốc gia đang phát triển đang trong quá trình công nghiệp hóa</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• The number of cars on our streets is growing</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Số lượng xe ô tô lưu thông trên đường phố tăng</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Cheap air travel is allowing more people to fly</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Du lịch hàng không giá rẻ cho phép nhiều người được đi máy bay</span></div><br><div style=\"display:flex;font-weight:700;font-size:0.88rem;color:var(--primary);margin:8px 0 4px;\"><span style=\"flex:1;padding-right:10px;\">Effects of Global Warming</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-weight:400;font-size:0.8rem;color:var(--text-muted);font-style:italic;\">Ảnh hưởng của sự nóng lên toàn cầu Global warming will have a significant impact on our planet</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span data-vi=\"1\" style=\"flex:1;font-size:0.82rem;\">Sự nóng lên toàn cầu có ảnh hưởng lớn đến trái đất chúng ta</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Rising temperature will cause melting of the polar ice caps</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Nhiệt độ tăng cao dẫn đến nguyên nhân băng tan ở bắc cực</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Sea levels will rise</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Mực nước biển sẽ tăng cao</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• We can expect more extreme weather conditions</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Chúng ta có thể hứng chịu thời tiết cực đoan</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Flooding and droughts may become more common</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Lũ lụt và hạn hán có thể xẩy ra thường xuyên hơn</span></div><br><div style=\"display:flex;font-weight:700;font-size:0.88rem;color:var(--primary);margin:8px 0 4px;\"><span style=\"flex:1;padding-right:10px;\">Impacts of humans on the environment</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-weight:400;font-size:0.8rem;color:var(--text-muted);font-style:italic;\">Tác động của con người đến môi trường</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• The increasing world population is putting pressure on natural resources</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Dân số thế giới gia tăng gây áp lực lên nguồn tài nguyên thiên nhiên</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Fossil fuels like oil and gas are running out</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Nhiên liệu hóa thạch như dầu và khí đang ngày càng cạn kiệt</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• We are destroying wildlife habitats</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Con người đang hủy hoại hệ sinh thái động vật</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• We have cut down enormous areas of rainforest</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Con người chặt phá một lượng lớn diện tích rừng</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• This has led to the extinction of many species of animals and plants</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Điều đó dẫn đến nhiều loại động vật và cây cối bị tuyệt chủng</span></div><br><div style=\"display:flex;font-weight:700;font-size:0.88rem;color:var(--primary);margin:8px 0 4px;\"><span style=\"flex:1;padding-right:10px;\">Solutions to environment problems</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-weight:400;font-size:0.8rem;color:var(--text-muted);font-style:italic;\">Giải pháp vấn đề môi trường Governments could introduce laws to limit emissions from factories</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span data-vi=\"1\" style=\"flex:1;font-size:0.82rem;\">Chính phủ nên ban hành luật pháp nhằm giảm khí thải công nghiệp</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• They should invest in renewable energy from solar, wind or water power</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Chính phủ nên đầu tư vào năng lượng thay thế như năng lượng mặt trời, năng lượng nước và năng lượng gió</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• They could impose “green taxes” on drivers and airlines companies</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Chính phủ có thể áp đặt thuế bảo vệ môi trường đối với lái xe và các hãng hàng không</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Government campaigns should promote recycling</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Chính phủ khởi động các chiến dịch tái chế sản phẩm</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Natural areas and wild animals should be protected</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Cần bảo vệ khu vực tự nhiên và các loại động vật hoang giã</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Individuals should also try to be greener</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Mỗi người cần phải có lối sống xanh hơn</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• We should take fewer flights abroad for holidays</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Chúng ta nên bớt lựa chọn đi bằng máy bay để du lịch nước ngoài</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• We should take public transport rather than driving</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Chúng ta nên chọn phương tiện công cộng thay cho lái xe riêng</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• We should choose products with less packaging</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Chúng ta nên chọn các sản phẩm ít sử dụng bao bì</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• We should recycle as much as possible</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Chúng ta nên tái sử dụng nhiều nhất có thể</span></div><br><div style=\"display:flex;font-weight:700;font-size:0.88rem;color:var(--primary);margin:8px 0 4px;\"><span style=\"flex:1;padding-right:10px;\">Waste/rubbish</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-weight:400;font-size:0.8rem;color:var(--text-muted);font-style:italic;\">Rác thải</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• The amount of waster we produce has increased</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Lượng rác của con người thải ra ngày càng tăng</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• This problem is a result of our consumer culture</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Vấn đề này là kết quả của nền văn hóa tiêu thụ</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Products are not made to last</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Các sản phẩm không bền</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• If something breaks, we throw it way and buy a new one</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Nếu một thứ hỏng, chúng ta ném nó đi và mua cái mới</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Advertisers encourage is to buy the newest fashions</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Những nhà quảng cáo khuyến khích khách hàng mua sản phẩm mới nhất</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Packaging is an important part of selling</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Bao bì là một phần quan trọng trong khâu bán hàng</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Most foods are sold in non-biodegradable plastics packaging</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Hầu hết thức ăn được bán trong các bao bì nilon không phân hủy The</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• amount of household waste is growing</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Lượng rác thải sinh hoạt ngày càng gia tăng</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• This waste ends up in landfill sites</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Rác thải này cuối cùng ngấm sâu vào lòng đất</span></div><br><div style=\"display:flex;font-weight:700;font-size:0.88rem;color:var(--primary);margin:8px 0 4px;\"><span style=\"flex:1;padding-right:10px;\">Litter</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-weight:400;font-size:0.8rem;color:var(--text-muted);font-style:italic;\">Rác rửa bừa bãi</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• People do not think about the consequences of dropping rubbish</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Con người không nghĩ đến hậu quả của việc vứt rác bừa bãi</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• They assume that somebody is pad to clean the street</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Họ cho rằng có người được trả lương để làm sạch đường phố</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Plastic packaging does not break down easily</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Bao bì không phân hủy được dễ dàng</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Most of the litter seen on streets is fast food packaging</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Hầu hết rách thấy trên đường là bao bì bọc thức ăn nhanh</span></div><br><div style=\"display:flex;font-weight:700;font-size:0.88rem;color:var(--primary);margin:8px 0 4px;\"><span style=\"flex:1;padding-right:10px;\">Recycling and other solutions</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-weight:400;font-size:0.8rem;color:var(--text-muted);font-style:italic;\">Tái chế và các giải pháp khác Companies should make goods that last longer</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span data-vi=\"1\" style=\"flex:1;font-size:0.82rem;\">Công ty nên sản xuất hàng hóa bền hơn</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• They should not use so much packaging</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Họ không nên sử dụng quá nhiều bao bì</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Governments should be stricter, about waster produced by companies</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Chính phủ nên nghiêm khắc hơn đối với rác thải công nghiệp</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• They should put legal limits on packaging</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Chính phủ nên đưa ra khung pháp lý về đóng gói sản phẩm</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Consumers should avoid buying over-packaged products</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Khách hàng nên tránh mua sản phẩm đóng gói kỹ càng</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• We should recycle and reuse useful materials.</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Chúng ta nên tái sử dụng chất liệu hữu dụng</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• There are collection banks for glass, paper and plastic bottles</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Có những nơi thu gom thủy tinh, giấy và các loại chai nhựa</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Households can use several rubbish bins to separate waste</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Các hộ gia đình nên có vài thùng rác để phân loại rác</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Recycling saves energy and raw materials.</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Tái chế tiết kiệm năng lượng và nguyên liệu thô 13. CRIME – TỘI PHẠM</span></div></div>"},
  {id:"crime", icon:"⚖️", label:"TỘI PHẠM", html:"<div style=\"font-size:0.85rem;line-height:1.6;\"><div style=\"display:flex;font-weight:700;font-size:0.88rem;color:var(--primary);margin:8px 0 4px;\"><span style=\"flex:1;padding-right:10px;\">Police and Crime Prevention</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-weight:400;font-size:0.8rem;color:var(--text-muted);font-style:italic;\">Cảnh sát và phòng chống tội phạm</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• The job of the polices is to catch criminals</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Công việc của cảnh sát là bắt kẻ phạm tội</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• They must also prevent crime and make communities safer</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Họ cũng phải có nhiệm vụ ngăn tội phạm và làm cho cộng đồng an toàn hơn</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• There should be an increase in the number of police officers on the streets</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Nên tăng số lượng cảnh sát trên đường phố</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Police officers should be seen as part of the community</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Cảnh sát nên là một phần của cộng đồng</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• They should be involved with education and prevention</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Cảnh sát nên tham gia vào việc giáo dục và phòng chống tội phạm</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• The police should be in close contact with schools</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Cảnh sát nên có mối liên hệ mật thiết với trường học</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• They should focus on young people who have dropped out of school. These teenagers may become involved with gangs</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Cảnh sát nên tập trung vào trẻ bỏ họ. Những đứa trẻ này có thể tham gia vào băng đảng tội phạm.</span></div><br><div style=\"display:flex;font-weight:700;font-size:0.88rem;color:var(--primary);margin:8px 0 4px;\"><span style=\"flex:1;padding-right:10px;\">Punishments/Prisons</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-weight:400;font-size:0.8rem;color:var(--text-muted);font-style:italic;\">Hình phạt/Nhà tù</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Fines are used as punishment for minor crimes</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Phạt tiền là một hình thức xử phạt dành cho kẻ phạm tội nhẹ</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• If the crime is more serious, prison is the most common punishment</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Nếu phạm tội ở mức nghiêm trọng thì phạt tù là hình thức xử phạt phổ biến nhất</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Some criminals pose a threat to society</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Một số tội phạm gây ra hiểm họa cho xã hội</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• They are put in prison to ensure the safety of other citizens</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Tống tội phạm vào tù để đảm bảo an toàn cho xã hội</span></div><br><div style=\"display:flex;font-weight:700;font-size:0.88rem;color:var(--primary);margin:8px 0 4px;\"><span style=\"flex:1;padding-right:10px;\">Negatives of prisons</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-weight:400;font-size:0.8rem;color:var(--text-muted);font-style:italic;\">Bất lợi của nhà tù</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Criminals are put together.</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Tội phạm thường bị giam chung với nhau</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• They make friends with other offenders</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Họ kết bạn với những tội phạm khác</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Many prisoners re-offend when they are released</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Nhiều tù nhân tái phạm khi được mãn hạn</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• A criminal record makes finding a job more difficult</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Tiền án phạm tội khiến học khó tìm việc làm</span></div><br><div style=\"display:flex;font-weight:700;font-size:0.88rem;color:var(--primary);margin:8px 0 4px;\"><span style=\"flex:1;padding-right:10px;\">Rehabilitation</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-weight:400;font-size:0.8rem;color:var(--text-muted);font-style:italic;\">Cải tạo</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Another aim of prisons is rehabilitation</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Mục đích của nhà tù là để cải tạo lại tù nhân</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Prisoners receive education of vocational training</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Tù nhân được đào tạo nghề</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Prisoners should learn personal skills and specific job skills</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Tù nhân nên học các kỹ năng cá nhân và các kỹ năng cần thiết cho nghề nhất định</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Punishment could make prisoners’ behavior worse</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Hình phạt ngồi tù có thể làm cho hành vi của tù nhân trở nên tồi tệ hơn</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Rehabilitation aims to make them better citizens</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Cải tạo nhằm mục đích giáo dục họ trở thành công dân tốt hơn</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Rehabilitated prisoners are less likely to re-offend</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Tù nhân sau cải tạo ít phạm tội lại</span></div><br><div style=\"display:flex;font-weight:700;font-size:0.88rem;color:var(--primary);margin:8px 0 4px;\"><span style=\"flex:1;padding-right:10px;\">Capital punishment</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-weight:400;font-size:0.8rem;color:var(--text-muted);font-style:italic;\">Tử hình</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Supporters say that capital punishment deters crime</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Những người ủng hộ cho rằng tử hình là hình thức để loại trừ tội phạm</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Fear of the death penalty stops people from committing offences</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Nỗi sợ tử hình sẽ khiến con người chùn bước trước phạm tội</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• The death penalty shows that crime is not tolerated</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Tử hình cho thấy rằng tội phạm không được khoan dung</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• It is a form of revenge</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Đó là một hình thức trả giá</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• The cost of imprisonment is avoided</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Có thể cắt được chi phí ngồi tù</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• The offender cannot pose a threat to others</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Phạm nhân không gây họa cho người khác</span></div><br><div style=\"display:flex;font-weight:700;font-size:0.88rem;color:var(--primary);margin:8px 0 4px;\"><span style=\"flex:1;padding-right:10px;\">Against Capital Punishment</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-weight:400;font-size:0.8rem;color:var(--text-muted);font-style:italic;\">Quan điểm phản đối với hình phạt tử hình Innocent people could be wrongly convicted and executed</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span data-vi=\"1\" style=\"flex:1;font-size:0.82rem;\">Những người vô tội có thể bị phán quyết và hành quyết sai</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Crime rates are not necessarily reduced</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Tỷ lệ tội phạm không giảm nhiều</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Many criminals do not think they will be caught</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Nhiều tội phạm không nghĩ rằng họ sẽ bị bắt</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Capital punishment is not a good deterrent</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Tử hình không phải là biện pháp phòng ngừa tội phạm tốt</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Executing prisoners creates a violent culture and encourages revenge</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Hành quyết tù nhân tạo ra văn hóa bạo lực và khuyến khích việc trả thù</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• We have no right to take another human life</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Chúng ta không có quyền tước đi quyền sống của người khác</span></div><br><div style=\"display:flex;font-weight:700;font-size:0.88rem;color:var(--primary);margin:8px 0 4px;\"><span style=\"flex:1;padding-right:10px;\">Community service</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-weight:400;font-size:0.8rem;color:var(--text-muted);font-style:italic;\">Lao động công ích</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Community service is a way to reform offenders</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Lao động công ích là cách để làm thay đổi tội phạm</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• It could be a solution to prison overcrowding</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Đó là giải pháp để giảm quá tải nhà tù</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• It avoids the cost of imprisonment</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Cắt giảm chi phí cho việc ngồi tù</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• It makes offenders useful in their local communities</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Nó khiến tội phạm hữu ích hơn đối với cộng đồng</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• They are required to clean streets or talk to school groups</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Tội phạm phải quét đường phố hoặc tham gia nói chuyện tại trường học</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Offenders repay their community</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Tội phạm bù đắp cho cộng đồng của họ</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• They avoid the negative influence that prison can have</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Họ tránh được những tác động tiêu cực mà nhà tù mang lại</span></div><br><div style=\"display:flex;font-weight:700;font-size:0.88rem;color:var(--primary);margin:8px 0 4px;\"><span style=\"flex:1;padding-right:10px;\">Against community service</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-weight:400;font-size:0.8rem;color:var(--text-muted);font-style:italic;\">Quan điểm về lao động công ích Community service is not a sufficient punishment</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span data-vi=\"1\" style=\"flex:1;font-size:0.82rem;\">Lao động công ích là hình thức xử phạt chưa đủ răn đe</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Criminals should be locked up, away from their victims</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Tội phạm có thể bị khóa và tránh xa nạn nhân</span></div><br><div style=\"display:flex;font-weight:700;font-size:0.88rem;color:var(--primary);margin:8px 0 4px;\"><span style=\"flex:1;padding-right:10px;\">Crime in the Media</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-weight:400;font-size:0.8rem;color:var(--text-muted);font-style:italic;\">Tội phạm trên truyền thông</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Crime is one of the main subjects of most news programs</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Tội phạm làm một chủ đề chính trên hầu hết các chương trình thời sự The</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• mass media focus on violent and sensational crimes</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Truyền thông tập trung vào các vụ lớn hoặc vụ việc tày trời</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• This lead to fear of crime among the public</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Điều này gây</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• hoang mang trong</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">dư luận</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Sensational stories attract more viewers or readers</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Các vụ việc tày trời thường lôi cuốn người xem, người đọc hơn.</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• The media report crime stories in order to increase their audience</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Truyền thông thuật lại vụ án nhằm tăng lượng độc giả</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• TOURISM – DU</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">LỊCH</span></div></div>"},
  {id:"tourism", icon:"✈️", label:"DU LỊCH", html:"<div style=\"font-size:0.85rem;line-height:1.6;\"><div style=\"display:flex;font-weight:700;font-size:0.88rem;color:var(--primary);margin:8px 0 4px;\"><span style=\"flex:1;padding-right:10px;\">Positives of Tourism</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-weight:400;font-size:0.8rem;color:var(--text-muted);font-style:italic;\">Ưu điểm của du lịch</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Tourism is a popular leisure activity</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Du lịch là một hoạt động giải trí phổ biến</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• People go on holiday to relax and have fun</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Mọi người đi du lịch để nghỉ ngơi và có giây phút vui vẻ</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Tourists can experience different cultures</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Du khách trải nghiệm các nền văn hóa khác nhau</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• They can sunbathe on beaches or go sight-seeing</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Họ có thể tắm nắng trên các bãi biển hay đi ngắm cảnh</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Travelling abroad opens our minds</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Du lịch nước ngoài mở mang trí óc</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• We can learn to speak other languages</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Chúng ta học nói ngôn ngữ khác</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• The tourist trade is vital for some economies</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Ngành du lịch có vai trò thiết yếu đối với một số nền kinh tế</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• It creates employment in services like accommodation, transport and entertainment</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Nó tạo công ăn, việc làm trong ngành dịch vụ như lưu trú, vận chuyển và giải trí</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Some areas rely on tourism for their income</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Một số địa phương kiếm thu nhập nhờ du lịch</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Tourists spend money</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Du khách tiêu tiền</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Tourism attracts investment from multi-national companies</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Du khách thu hút sự đầu tư từ các công ty đa quốc gia</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• It helps to improve the standard of living</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Nó giúp cải thiện chất lượng cuộc sống</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Low-cost airlines are making it cheaper to travel abroad</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Các hãng hàng không giá rẻ cung cấp giá vé rẻ hơn cho du khách đi du lịch nước ngoài</span></div><br><div style=\"display:flex;font-weight:700;font-size:0.88rem;color:var(--primary);margin:8px 0 4px;\"><span style=\"flex:1;padding-right:10px;\">Negative effects of tourism</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-weight:400;font-size:0.8rem;color:var(--text-muted);font-style:italic;\">Nhược điểm của du lịch</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Tourism can have a negative effect on the natural environment</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Du lịch có thể ảnh hưởng tiêu cực lên môi trường tự nhiên</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• The building of facilities and infrastructure can destroy the habitat of wild animals</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Xây dựng cơ sở vật chất có thể phá hủy môi trường sống của các loại động vật hoang giã</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Beautiful beaches are spoilt by the building of hotels</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Các bãi biệt đẹp bị phá hỏng khi các khác sạn xây dựng</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Tourism creates pollution and waste</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Du lịch gây ô nhiễm và rác thải</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• It puts pressure on local resources</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Du lịch tạo các áp lực lên nguồn lực địa phương</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Local traditional and cultures may be endangered</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Truyền thống và văn hóa bản địa có thể bị đe dọa</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• A rise in the cost of living affects local people</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Tăng chi phí sinh hoạt ảnh hưởng đến người dân địa phương</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• The price of goods, services and housing may increase significantly</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Giá của các hàng hóa, dịch vụ và lưu trú có thể tăng lên đáng kể</span></div><br><div style=\"display:flex;font-weight:700;font-size:0.88rem;color:var(--primary);margin:8px 0 4px;\"><span style=\"flex:1;padding-right:10px;\">The future of tourism</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-weight:400;font-size:0.8rem;color:var(--text-muted);font-style:italic;\">Xu hướng du lịch</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Government should introduce laws to protect natural environments and local cultures</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Chính phủ nên ban hành luật bảo vệ môi trường tự nhiên và văn hóa bản địa</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Tourism should have a low impact on wildlife</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Du lịch cần ít gây ảnh hưởng đến các loại động vật hoang giã</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Renewable resources like solar or water power should be used</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Nên sử dụng các nguồn năng lượng thay thế như năng lượng mặt trời hay hơi nước</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Waste should be recycled</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Cần tái chế rác thải</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Local businesses such as farms should be supported</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Cần hỗ trợ các ngành nghề kinh doanh bản địa như ngành nông nghiệp</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• GOVERNMENT AND SOCIETY –</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">CHÍNH PHỦ VÀ XÃ HỘI</span></div></div>"},
  {id:"government", icon:"🏛️", label:"CHÍNH PHỦ", html:"<div style=\"font-size:0.85rem;line-height:1.6;\"><div style=\"display:flex;font-weight:700;font-size:0.88rem;color:var(--primary);margin:8px 0 4px;\"><span style=\"flex:1;padding-right:10px;\">What governments can do</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-weight:400;font-size:0.8rem;color:var(--text-muted);font-style:italic;\">Những việc chính phủ cần làm</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Governments provide public services like healthcare and education</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Chính phủ cần cung cấp các dịch vụ công cộng như giáo dục và y tế</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• They support people who are living in poverty or unable to work</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Chính phủ hỗ trợ người nghèo và những người không thể làm việc</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Governments raise money by taxing working people</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Chính phủ quyên góp tiền bằng cách đánh thuế người lao động</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• They can spend money on resources and campaigns</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Chính phủ chi tiêu vào các nguồn lực và các chiến dịch</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• They can introduce new laws</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Nhà nước ban hành pháp luật mới</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• They can impose taxes</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Nhà nước đánh thuế</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• They can raise people’s awareness of issues (e.g climate change/healthy eating)</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Nhà nước nâng cao nhận thức của con người dân (ví dụ như thay đổi thời tiết/ ăn uống lành mạnh)</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• They can influence people’s habits and opinions</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Nhà nước gây ảnh hưởng đến thói quen và quan điểm của người dân</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• They can create jobs</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Nhà nước tạo công việc làm ăn</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• They can regulate the activities of companies such as banks</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Nhà nước điều phối các hoạt động của các ngân hàng</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• They can provide resources for schools</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Nhà nước cung cấp các nguồn lợi cho trường học</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• They are also responsible for the security and well-being of their citizens</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Nhà nước cũng phụ trách an ninh và phúc lợi xã hội cho người dân</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• They control armed forces and police forces</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Nhà nước quản lý các lực lượng vũ trang và cảnh sát</span></div><br><div style=\"display:flex;font-weight:700;font-size:0.88rem;color:var(--primary);margin:8px 0 4px;\"><span style=\"flex:1;padding-right:10px;\">Public services</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-weight:400;font-size:0.8rem;color:var(--text-muted);font-style:italic;\">Dịch vụ công</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Governments pay the salaries of public sector workers like police officers and teachers</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Chính phủ trả lương cho công nhân như cảnh sát và giáo viên</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• The necessary money is raised by taxing people’s income</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Quyên góp tiền bằng cách đóng góp thuế thu nhập cá nhân</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Free education and healthcare may be provided by the state</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Nhà nước có thể cung cấp giáo dục và ý tế miễn phí</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Some governments control public transport systems and even TV channels</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Một số chính phủ quản lý hệ thống giao thông công cộng và thậm chí là các kênh truyền hình</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• In other countries, these services are provided by private companies</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Ở một số quốc gia khác, dịch vụ này do các công ty chuyên trách quản lý</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Some people believe that competition between private companies is good</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Một số người cho rằng cạnh tranh giữa các công ty tư nhân có lợi</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• It helps to improve quality while bringing prices down</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Cạnh tranh giúp cải tiến chất lượng, đồng thời giảm giá thành sản phẩm</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Other people think that essential services should be free</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Một số người khác cho rằng, dịch phụ thiết yếu nên được miễn phí</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Governments should pay for them</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Chính phủ sẽ trợ cấp những dịch vụ thiết yếu 16. GLOBALIZATION – TOÀN CẦU HÓA</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Positives of Globalization -</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Lợi ích của toàn cầu hóa</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Multi-national companies do business across the world</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Công ty đa quốc gia kinh doanh trên toàn thế giới</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Companies like MacDonald’s can be seen on high streets in most cities</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Các công ty như MacDonald có thể bắt gặp ở các con phố lớn ở hầu hết các thành phố</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Goods are produced in one country and sold in many others</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Hàng hóa được sản xuất ở một quốc gia và bản ở nhiều quốc gia</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• A global economy means free trade between countries</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Một nền kinh tế toàn cầu đồng nghĩa với việc tự do thương mại giữa các nước</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• This can strengthen political relationships</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Tự do thương mại có thể tăng cường mối quan hệ chính trị</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Globalization can also create opportunities for employment</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Toàn cầu hóa cũng có thể tạo thêm cơ hội việc làm</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• It encourages investment in less developed countries</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Nó khuyến khích đầu tư vào các quốc gia kém phát triển</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• It could reduce poverty in the developing world</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Nó làm giảm nghèo đói ở các quốc gia đang phát triển</span></div></div>"},
  {id:"globalization", icon:"🌐", label:"TOÀN CẦU HÓA", html:"<div style=\"font-size:0.85rem;line-height:1.6;\"><div style=\"display:flex;font-weight:700;font-size:0.88rem;color:var(--primary);margin:8px 0 4px;\"><span style=\"flex:1;padding-right:10px;\">Negatives of Globalization</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-weight:400;font-size:0.8rem;color:var(--text-muted);font-style:italic;\">Bất lợi của toàn cầu hóa</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Globalization is not always beneficial to everyone</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Toàn cầu hóa không mang lại lợi ích cho toàn thể mọi người</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Companies can move to countries where labour is cheap</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Các công ty có thể chuyến tới các nước có nguồn nhân công rẻ mạt</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• This creates redundancies, or job losses</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Điều này dẫn đến mất việc/thất nghiệp</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Employees cannot be confident that they have stable jobs</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Người lao động không thể tự tin rằng mình có việc làm ổn định</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Companies sometimes exploit their employees in developing countries</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Đôi khi các công ty cũng thuê nhân viên ở các quốc gia đang phát triển</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Global trade creates more waste and pollution</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Thương mại toàn cầu gây ra lãng phí và ô nhiễm hơn</span></div><br><div style=\"display:flex;font-weight:700;font-size:0.88rem;color:var(--primary);margin:8px 0 4px;\"><span style=\"flex:1;padding-right:10px;\">The future of globalization</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-weight:400;font-size:0.8rem;color:var(--text-muted);font-style:italic;\">Xu hướng toàn cầu hóa</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• There should be global regulations for salaries and working conditions</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Nên có quy tắc chung về mức lương và điều kiện làm việc</span></div><div style=\"display:flex;margin-bottom:5px;line-height:1.5;\"><span style=\"flex:1;padding-right:10px;\">• Governments should impose laws to protect the environment</span><span data-vi=\"1\" style=\"flex:1;padding-left:10px;border-left:1px solid var(--border-color);font-size:0.82rem;color:var(--text-muted);font-style:italic;\">Chính phủ nên áp đặt luật bảo vệ môi trường</span></div></div>"}
];